import{_ as t,o as n,c as i,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2019-04-10 :: Ceph Testing meeting","description":"","frontmatter":{"title":"2019-04-10 :: Ceph Testing meeting","date":"2019-04-10T00:00:00.000Z","updated":"2019-04-12T00:00:00.000Z","tags":["Ceph","测试","分布式存储","Jenkins","OpenStack"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-04-10_-_-_Ceph_Testing_meeting.md","filePath":"posts/2019/2019-04-10_-_-_Ceph_Testing_meeting.md","lastUpdated":1780460162000}'),s={name:"posts/2019/2019-04-10_-_-_Ceph_Testing_meeting.md"};function o(r,e,a,p,_,g){return n(),i("div",null,[...e[0]||(e[0]=[l('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年11月某日</p><p><strong>参会人员</strong>： 未知</p><p><strong>会议主题</strong>： Ceph 存储集群测试与部署</p><p><strong>会议内容</strong>：</p><p><strong>1. 近期工作回顾</strong></p><ul><li>会议回顾了过去几周的工作情况，由于部分成员缺席，对具体工作进展了解有限。</li><li>Kiran 分享了在测试环境中的 Rock Orchestrator 部署经验，但未明确其整合方案。</li></ul><p><strong>2. Jenkins 测试</strong></p><ul><li>目前上游 Jenkins 测试主要依靠 Jenkins Slave 系统自动执行，如 Alfredo 创建的系统。</li><li>David Galloway 负责管理 Jenkins 环境。</li><li>讨论了如何将测试集成到 Jenkins 中，并触发相关操作。</li></ul><p><strong>3. 部署测试</strong></p><ul><li>讨论了将测试部署到虚拟机中的方法，包括使用电话设置虚拟机、部署集群和执行测试。</li><li>目前上游尚无直接将测试部署到虚拟机中的方案，但可以考虑参考 Jenkins 测试方案。</li></ul><p><strong>4. smoke 测试</strong></p><ul><li>讨论了 smoke 测试的执行方式，包括在 Jenkins 上运行和针对不同分支执行。</li><li>认为在 Jenkins 上运行 smoke 测试可以提供快速反馈，并减少人工干预。</li></ul><p><strong>5. OpenStack 部署测试</strong></p><ul><li>讨论了在 OpenStack 上进行部署测试的方法，包括使用 OpenStack API 和创建镜像。</li><li>认为需要实现类似功能，以便在测试环境中使用 OpenStack。</li></ul><p><strong>6. Other</strong></p><ul><li>讨论了不同测试套件的执行时间，以及如何优化测试流程。</li><li>认为需要进一步研究 smoke 测试的执行时间，以便提高测试效率。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Kiran 将分享 Rock Orchestrator 部署经验。</li><li>David Galloway 将介绍 Jenkins 环境设置。</li><li>尝试将 smoke 测试集成到 Jenkins 中。</li><li>研究在 OpenStack 上进行部署测试的方法。</li><li>优化测试流程，提高测试效率。</li></ul><p><strong>备注</strong>：</p><ul><li>会议中涉及部分计算机科学/ceph相关领域英文原文的关键词，如：Rock Orchestrator、Jenkins、smoke 测试、OpenStack、Alfredo、David Galloway、PR、CI/CD、虚拟机等。</li></ul>',21)])])}const d=t(s,[["render",o]]);export{c as __pageData,d as default};
